'use strict';

/**
 * managed-block.cjs — the versioned AOFORGE:START/END block (TRD 36-02, UPG-02).
 *
 *   <!-- AOFORGE:START v=<ver> src=<template> -->
 *   ...generated content...
 *   <!-- AOFORGE:END -->
 *
 * The legacy marker written by map-codebase before objective 36 carries no version:
 *
 *   <!-- AOFORGE:START - Auto-generated by /aoforge:map-codebase. Edit between these markers ... -->
 *
 * It parses as `{v: null, src: null, legacy: true}` and is always stale.
 *
 * Guarantees:
 *   - Every byte outside the block is preserved: replacement is `text.slice(0, start) + block +
 *     text.slice(end)`, never a split/join over lines, so CRLF and trailing whitespace survive.
 *   - Two blocks, or a START with no END after it, throw ManagedBlockError. `upsert` rethrows, so a
 *     caller that writes the result never writes on the malformed path.
 *   - `v` is the TEMPLATE version (the template's `template_version`), not the plugin version.
 *
 * Deliberately generic: no CLAUDE.md knowledge lives here (objective 38 reuses it), and it requires
 * no module at all — sync-runtime tests copy it into a fake plugin root (36-06).
 */

const START_RE = /<!--\s*AOFORGE:START\b([^>]*?)\s*-->/g;
const END_RE = /<!--\s*AOFORGE:END\s*-->/g;
const V_ATTR_RE = /(?:^|\s)v=([^\s>]+)/;
const SRC_ATTR_RE = /(?:^|\s)src=([^\s>]+)/;
const SINGLE_START_RE = /^<!--\s*AOFORGE:START\b([^>]*?)\s*-->$/;
const ATTR_VALUE_RE = /^[^\s>]+$/;

class ManagedBlockError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ManagedBlockError';
  }
}

function metaFromAttrs(attrs) {
  const v = V_ATTR_RE.exec(attrs);
  if (!v) return { v: null, src: null, legacy: true };
  const src = SRC_ATTR_RE.exec(attrs);
  return { v: v[1], src: src ? src[1] : null, legacy: false };
}

/**
 * Parse a single START marker string. Returns `{v, src, legacy}` or null when the string is not a
 * AOFORGE:START marker. A marker without `v=` is legacy.
 */
function parseStartMarker(marker) {
  if (typeof marker !== 'string') return null;
  const m = SINGLE_START_RE.exec(marker.trim());
  return m ? metaFromAttrs(m[1]) : null;
}

function allMatches(re, text) {
  const out = [];
  const rx = new RegExp(re.source, 'g');
  let m;
  while ((m = rx.exec(text)) !== null) out.push(m);
  return out;
}

/**
 * Locate the managed block in `text`.
 *
 * @returns {null | {start:number, end:number, content:string, meta:{v, src, legacy}}}
 *   `start` is the index of the START marker, `end` the index just past the END marker.
 *   `content` is the text between the markers minus exactly one leading and one trailing newline
 *   (`\n` or `\r\n`).
 * @throws {ManagedBlockError} on more than one START, or a START with no END after it.
 */
function read(text) {
  if (typeof text !== 'string') throw new TypeError('managed-block read: text must be a string');
  const starts = allMatches(START_RE, text);
  if (starts.length === 0) return null; // an END with no START is not a block
  if (starts.length > 1) {
    throw new ManagedBlockError(`multiple AOFORGE blocks (${starts.length} START markers); refusing to edit`);
  }
  const s = starts[0];
  const innerStart = s.index + s[0].length;
  const endRx = new RegExp(END_RE.source, 'g');
  endRx.lastIndex = innerStart; // only an END after the START closes it
  const e = endRx.exec(text);
  if (!e) throw new ManagedBlockError('unterminated AOFORGE block (START marker without a following END)');

  let content = text.slice(innerStart, e.index);
  if (content.startsWith('\r\n')) content = content.slice(2);
  else if (content.startsWith('\n')) content = content.slice(1);
  if (content.endsWith('\r\n')) content = content.slice(0, -2);
  else if (content.endsWith('\n')) content = content.slice(0, -1);

  return { start: s.index, end: e.index + e[0].length, content, meta: metaFromAttrs(s[1]) };
}

function attrValue(name, value, required) {
  if (value === undefined || value === null || value === '') {
    if (required) throw new ManagedBlockError(`render: meta.${name} is required`);
    return null;
  }
  const str = String(value);
  if (!ATTR_VALUE_RE.test(str)) {
    throw new ManagedBlockError(`render: meta.${name} must not contain whitespace or '>' (got ${JSON.stringify(str)})`);
  }
  return str;
}

/**
 * Render a versioned block. Trailing newlines in `content` collapse to none; exactly one newline
 * separates content from each marker. No trailing newline after END.
 */
function render(content, meta = {}) {
  const v = attrValue('v', meta.v, true);
  const src = attrValue('src', meta.src, false);
  const body = String(content == null ? '' : content).replace(/(?:\r?\n)+$/, '');
  const attrs = src ? `v=${v} src=${src}` : `v=${v}`;
  return `<!-- AOFORGE:START ${attrs} -->\n${body}\n<!-- AOFORGE:END -->`;
}

function appendSeparator(text) {
  if (text === '') return '';
  if (/(?:\r?\n){2}$/.test(text)) return '';
  if (/\r?\n$/.test(text)) return '\n';
  return '\n\n';
}

/**
 * Replace the existing block (bytes outside it untouched) or add a new one.
 *
 * @param {string} text
 * @param {string} content
 * @param {{v:string, src?:string}} meta
 * @param {{position?: 'append'|'prepend'}} [opts]
 * @throws {ManagedBlockError} when the existing text is malformed (rethrown from read)
 */
function upsert(text, content, meta, { position = 'append' } = {}) {
  if (typeof text !== 'string') throw new TypeError('managed-block upsert: text must be a string');
  if (position !== 'append' && position !== 'prepend') {
    throw new ManagedBlockError(`upsert: position must be 'append' or 'prepend' (got ${JSON.stringify(position)})`);
  }
  const block = render(content, meta);
  const existing = read(text); // throws on malformed; never falls through to a second block
  if (existing) return text.slice(0, existing.start) + block + text.slice(existing.end);
  if (text === '') return `${block}\n`;
  if (position === 'prepend') return `${block}\n\n${text}`;
  return `${text}${appendSeparator(text)}${block}\n`;
}

/**
 * Numeric dotted compare: '10' > '9', '1.10' > '1.2', missing parts are 0. Non-numeric parts count
 * as 0. Returns -1, 0 or 1.
 */
function compareVersions(a, b) {
  const pa = String(a).split('.');
  const pb = String(b).split('.');
  const n = Math.max(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const x = Number(pa[i] || 0) || 0;
    const y = Number(pb[i] || 0) || 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

/**
 * True when the block is legacy or its `v` is lower than `ver`. Accepts a block object (from
 * `read`) or raw text. No block → false (there is nothing stale to rewrite).
 */
function isStale(blockOrText, ver) {
  const block = typeof blockOrText === 'string' ? read(blockOrText) : blockOrText;
  if (!block) return false;
  if (!block.meta || block.meta.legacy || block.meta.v == null) return true;
  return compareVersions(block.meta.v, ver) < 0;
}

module.exports = {
  read,
  render,
  upsert,
  isStale,
  parseStartMarker,
  compareVersions,
  ManagedBlockError,
  START_RE,
  END_RE,
};
